import {useMemo} from 'react'
import {ActionList} from '@primer/react'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import type {DefaultModel} from '../types'
import {CustomModelRule} from './CustomModelRule'
import {DefaultModelRule} from './DefaultModelRule'
import {RulesListBlankslate} from './RulesListBlankslate'
import {getCustomKeysByModelId} from '../utils/custom-keys'

export function ModelRulesList({
  customKeys,
  models,
  orgDisplayLogin,
}: {
  customKeys: CustomKey[]
  models: Array<CustomModel | DefaultModel>
  orgDisplayLogin: string
}) {
  const {allowedCustomModelIds, allowedModelKeys, isAllowlist} = useOrganizationAccessPolicy()

  const targetedModels = useMemo(() => {
    return models.filter(model => {
      const isModelAllowed =
        ('key' in model && allowedModelKeys.has(model.key)) || ('id' in model && allowedCustomModelIds.has(model.id))
      return isAllowlist ? isModelAllowed : !isModelAllowed
    })
  }, [allowedCustomModelIds, allowedModelKeys, isAllowlist, models])

  const customKeysByModelId = useMemo(() => getCustomKeysByModelId({customKeys, models}), [customKeys, models])

  if (targetedModels.length < 1) {
    return <RulesListBlankslate isAllowlist={isAllowlist} />
  }

  return (
    <ActionList className="Box-body px-0" aria-label="Model rules">
      {targetedModels.map(model => {
        if ('publisherId' in model) {
          return (
            <DefaultModelRule model={model} key={`model-${isAllowlist ? 'allowed' : 'blocked'}-rule-${model.key}`} />
          )
        }
        const customKey = customKeysByModelId.get(model.id)
        if (customKey) {
          return (
            <CustomModelRule
              customKey={customKey}
              orgDisplayLogin={orgDisplayLogin}
              model={model}
              key={`model-${isAllowlist ? 'allowed' : 'blocked'}-rule-${model.id}`}
            />
          )
        }
        return null
      })}
    </ActionList>
  )
}

try{ ModelRulesList.displayName ||= 'ModelRulesList' } catch {}