import {Checkbox, Label, TreeView} from '@primer/react'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import {useSelection} from '../contexts/SelectionContext'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import {CustomModelSelectionItem} from './CustomModelSelectionItem'
import {testIdProps} from '@github-ui/test-id-props'
import {isSubsetOf, setIntersection} from '../utils/set-utils'
import {ProviderLogo} from '@github-ui/models-byok/providers/ProviderLogo'
import styles from './CustomKeySelectionItem.module.css'

export function CustomKeySelectionItem({customKey, models}: {customKey: CustomKey; models: CustomModel[]}) {
  const {isAllowlist} = useOrganizationAccessPolicy()
  const {selectedCustomModelIds, selectModels, deselectModels} = useSelection()
  const modelsForCustomKey = models.filter(model => model.customKeyId === customKey.id)
  const modelIdsForCustomKey = new Set(modelsForCustomKey.map(model => model.id))
  const selectedModelIdsForCustomKey = setIntersection(modelIdsForCustomKey, selectedCustomModelIds)
  const anyModelsForCustomKeySelected = selectedModelIdsForCustomKey.size > 0
  const allModelsForCustomKeySelected = isSubsetOf(selectedCustomModelIds, modelIdsForCustomKey)
  const customKeyModelUnits = customKey.totalModels === 1 ? 'model' : 'models'

  return (
    <TreeView.Item
      id={`customKey-${isAllowlist ? 'allow' : 'block'}-${customKey.id}`}
      current={allModelsForCustomKeySelected}
      onSelect={() =>
        allModelsForCustomKeySelected ? deselectModels(modelIdsForCustomKey) : selectModels(modelIdsForCustomKey)
      }
      aria-label={customKey.name}
    >
      <TreeView.LeadingVisual>
        <Checkbox
          indeterminate={anyModelsForCustomKeySelected && !allModelsForCustomKeySelected}
          checked={allModelsForCustomKeySelected}
          aria-label={`Select ${customKey.name}`}
          readOnly
          {...testIdProps(`customKey-checkbox-${customKey.id}`)}
        />
      </TreeView.LeadingVisual>
      <div className={styles.CustomKeySelectionItem}>
        <ProviderLogo className={styles.CustomKeySelectionItemProviderLogo} provider={customKey.provider} />
        <span data-area="name">{customKey.name}</span>
        <span data-area="meta" data-small-text={`(${selectedModelIdsForCustomKey.size}/${customKey.totalModels})`}>
          {selectedModelIdsForCustomKey.size} of {customKey.totalModels} {customKeyModelUnits} selected
        </span>
        <Label>Custom</Label>
      </div>
      <TreeView.SubTree state="done" count={modelsForCustomKey.length} aria-label={`Models from ${customKey.name}`}>
        {modelsForCustomKey.map(model => (
          <CustomModelSelectionItem model={model} key={`model-${isAllowlist ? 'allow' : 'block'}-${model.id}`} />
        ))}
      </TreeView.SubTree>
    </TreeView.Item>
  )
}

try{ CustomKeySelectionItem.displayName ||= 'CustomKeySelectionItem' } catch {}