import {ActionList, ActionMenu, Heading, Link, Spinner, Stack} from '@primer/react'
import {useCallback, useId, useMemo} from 'react'
import {
  disableModelsBillingPayload,
  enableModelsBillingPayload,
  useUpdateOrganizationBilling,
} from '../hooks/use-update-organization-billing'
import {AlertFillIcon, AlertIcon, ShieldLockIcon} from '@primer/octicons-react'
import styles from './ModelsBilling.module.css'
import {modelsPricingLink} from '../constants'
import {testIdProps} from '@github-ui/test-id-props'
import {orgBillingUsagePath} from '@github-ui/paths'

export function ModelsBilling({
  billingEnabled,
  orgDisplayLogin,
  canEnableModelsBilling,
  businessBillingEnabled,
  hideBilling,
  isBusinessAdmin,
  businessSlug,
  paymentMethodRequired,
  invoiced,
  legacy = false,
}: {
  billingEnabled: boolean
  orgDisplayLogin: string
  canEnableModelsBilling: boolean
  businessBillingEnabled: boolean
  hideBilling: boolean
  isBusinessAdmin: boolean
  businessSlug?: string
  paymentMethodRequired: boolean
  invoiced: boolean
  legacy?: boolean
}) {
  const billingBudgetsPath = businessSlug
    ? `/enterprises/${businessSlug}/billing/budgets`
    : `/organizations/${orgDisplayLogin}/settings/billing/budgets`
  const billingPaymentInfoPath = `/organizations/${orgDisplayLogin}/settings/billing/payment_information`
  const docsPath = 'https://docs.github.com/github-models/use-github-models/prototyping-with-ai-models#rate-limits'

  const {
    data: updatedModelsBillingValue,
    mutate: updateOrganizationModelsBilling,
    isPending: isUpdatePending,
    isError: didUpdateError,
  } = useUpdateOrganizationBilling({orgDisplayLogin})
  const errorMessageId = useId()

  const modelsBillingEnabled = useMemo(() => {
    return updatedModelsBillingValue?.enabled ?? billingEnabled
  }, [updatedModelsBillingValue?.enabled, billingEnabled])

  const billingDetailsPath = useCallback(() => {
    if (businessSlug && isBusinessAdmin) {
      return `/enterprises/${businessSlug}/billing/usage?query=product:models`
    }
    return orgBillingUsagePath({org: orgDisplayLogin, query: `product:models`})
  }, [businessSlug, isBusinessAdmin, orgDisplayLogin])

  const showBillingDetails = businessSlug ? isBusinessAdmin && businessBillingEnabled : modelsBillingEnabled

  if (hideBilling) return null

  const showBudgetsLink = !businessSlug || isBusinessAdmin

  return (
    <>
      <Heading as="h2" data-hpc variant="small" className="mt-4 mb-2">
        Billing
      </Heading>
      <Stack direction="vertical" gap="none">
        <div className={styles.container}>
          <Stack direction="horizontal" gap="condensed" justify="space-between">
            <Stack direction="vertical" gap="condensed" className="mr-4">
              <Heading as="h3" variant="small">
                Models paid usage
              </Heading>
              <p className="fgColor-muted mb-0">
                If enabled, models usage will be billed per token based on model pricing from your Model&apos;s budget.
              </p>
              <span>
                {showBillingDetails && (
                  <Link inline href={billingDetailsPath()} className="mr-3">
                    View billing details
                  </Link>
                )}
                <Link inline href={modelsPricingLink}>
                  Models pricing
                </Link>
              </span>
            </Stack>
            {canEnableModelsBilling ? (
              <Stack justify="center">
                <ActionMenu>
                  <ActionMenu.Button
                    disabled={isUpdatePending}
                    aria-describedby={didUpdateError ? errorMessageId : undefined}
                    leadingVisual={() => {
                      if (didUpdateError) return <AlertIcon />
                      if (isUpdatePending) return <Spinner size="small" />
                      return null
                    }}
                    className={didUpdateError ? 'mr-3' : undefined}
                  >
                    <span className="sr-only">Models billing status: </span>
                    <span>{modelsBillingEnabled ? 'Enabled' : 'Disabled'}</span>
                  </ActionMenu.Button>
                  <ActionMenu.Overlay>
                    {!isUpdatePending && (
                      <ActionList selectionVariant="single" variant="full" showDividers>
                        <ActionList.Item
                          selected={modelsBillingEnabled}
                          onSelect={() => updateOrganizationModelsBilling(enableModelsBillingPayload())}
                        >
                          Enabled
                          <ActionList.Description variant="block">
                            Organization will allow Models paid usage.
                          </ActionList.Description>
                        </ActionList.Item>
                        <ActionList.Item
                          selected={!modelsBillingEnabled}
                          onSelect={() => updateOrganizationModelsBilling(disableModelsBillingPayload())}
                        >
                          Disabled
                          <ActionList.Description variant="block">
                            Organization will have free rate limits.
                          </ActionList.Description>
                        </ActionList.Item>
                      </ActionList>
                    )}
                  </ActionMenu.Overlay>
                </ActionMenu>
                {didUpdateError && (
                  <div id={errorMessageId} className="fgColor-danger">
                    There was a problem enabling/disabling billing for Models. Please try again later.
                  </div>
                )}
              </Stack>
            ) : (
              <Stack align="center" direction="horizontal" className="color-fg-muted">
                <ShieldLockIcon size="small" /> <span>Disabled</span>
              </Stack>
            )}
          </Stack>
          {paymentMethodRequired && (
            <Stack className="fgColor-attention pt-3 gap-1" direction="horizontal" align="center">
              <AlertFillIcon />
              <p className="mb-0">
                To enable Models paid usage, a payment method is needed.{' '}
                {invoiced ? (
                  <Link inline href="/contact" className="fgColor-attention">
                    Contact sales to add payment method
                  </Link>
                ) : (
                  <Link inline href={billingPaymentInfoPath} className="fgColor-attention">
                    Add payment method
                  </Link>
                )}
                <span>.</span>
              </p>
            </Stack>
          )}
          {legacy && (
            <Stack className="fgColor-attention pt-3 gap-1" direction="horizontal" align="center">
              <AlertFillIcon />
              <p className="mb-0">
                This plan does not support additional Models usage.{' '}
                <Link
                  inline
                  href="https://docs.github.com/en/billing/managing-billing-for-your-products/about-billing-for-github-models"
                  className="fgColor-attention"
                >
                  Learn more about Models billing
                </Link>
                .
              </p>
            </Stack>
          )}
        </div>
        <Stack>
          <div className={styles.footer}>
            <div className="fgColor-muted mb-0" {...testIdProps('models-billing-footer')}>
              {modelsBillingEnabled ? (
                <>
                  A budget greater than $0 is required for Models paid usage.{' '}
                  {showBudgetsLink && (
                    <>
                      <Link inline href={billingBudgetsPath}>
                        Adjust Model&apos;s budget
                      </Link>
                      .
                    </>
                  )}
                  <p className="mt-2">If a budget is already set, no action is needed.</p>
                </>
              ) : businessSlug && !businessBillingEnabled ? (
                <>
                  Your organization has{' '}
                  <Link inline href={docsPath}>
                    free rate limits
                  </Link>
                  . Request your enterprise to turn on billing to avoid interruptions and enable paid usage.
                </>
              ) : (
                <>
                  Your organization has{' '}
                  <Link inline href={docsPath}>
                    free rate limits
                  </Link>
                  . Turn on billing for Models paid usage to avoid interruptions.
                </>
              )}
            </div>
          </div>
        </Stack>
      </Stack>
    </>
  )
}

try{ ModelsBilling.displayName ||= 'ModelsBilling' } catch {}