import {Checkbox, Label, TreeView} from '@primer/react'
import {testIdProps} from '@github-ui/test-id-props'
import {useOrganizationAccessPolicy} from '../contexts/OrganizationAccessPolicyContext'
import type {CustomModel} from '@github-ui/models-byok/types'
import {useSelection} from '../contexts/SelectionContext'

interface CustomModelSelectionItemProps {
  model: CustomModel
}

export function CustomModelSelectionItem({model}: CustomModelSelectionItemProps) {
  const {isAllowlist} = useOrganizationAccessPolicy()
  const {selectedCustomModelIds, selectModels, deselectModels} = useSelection()
  const isSelected = selectedCustomModelIds.has(model.id)
  const modelName = model.name ?? model.slug

  return (
    <TreeView.Item
      id={`model-${isAllowlist ? 'allow' : 'block'}-${model.id}`}
      current={isSelected}
      aria-label={modelName}
      onSelect={() => (isSelected ? deselectModels([model.id]) : selectModels([model.id]))}
    >
      <div className="d-flex flex-items-center flex-justify-between">
        <div className="d-flex flex-items-center">
          <Checkbox
            value={model.id.toString()}
            className="mr-2"
            checked={isSelected}
            aria-label={`Select ${modelName}`}
            readOnly
            {...testIdProps(`model-checkbox-${model.id}`)}
          />
          {modelName}
          {model.slug && model.slug !== modelName && <span className="fgColor-muted">&nbsp;{model.slug}</span>}
        </div>
        <Label>Custom</Label>
      </div>
    </TreeView.Item>
  )
}

try{ CustomModelSelectionItem.displayName ||= 'CustomModelSelectionItem' } catch {}